import React, { useEffect, useState } from "react";
import axios from "axios";
import { useParams } from "react-router-dom";

const UserBlogs = () => {
  const { userId } = useParams(); // Lấy userId từ URL
  const [blogs, setBlogs] = useState([]);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchUserBlogs = async () => {
      try {
        const token = localStorage.getItem("token"); // Lấy token từ localStorage
        if (!token) {
          setError("Bạn chưa đăng nhập!");
          return;
        }

        const res = await axios.get(`http://localhost:9999/getuserblog/${userId}`, {
          headers: { Authorization: `Bearer ${token}` }, // Gửi token trong headers
        });

        setBlogs(res.data.blogs);
      } catch (err) {
        setError(err.response?.data?.message || "Lỗi khi tải bài viết của bạn.");
      }
    };

    fetchUserBlogs();
  }, [userId]);

  if (error) return <p>{error}</p>;

  return (
    <div>
      <h2>Bài viết của bạn</h2>
      {blogs.length > 0 ? (
        blogs.map((blog) => <p key={blog._id}>{blog.title}</p>)
      ) : (
        <p>Chưa có bài viết nào.</p>
      )}
    </div>
  );
};

export default UserBlogs;
